def binomialModPrime(n, r, p):
    fact = [1] * p
    for i in range(1, p):
        fact[i] = fact[i - 1] * i % p

    def small(a, b):
        if b > a:
            return 0
        return fact[a] * pow(fact[b] * fact[a - b] % p, p - 2, p) % p

    result = 1
    while n or r:
        result = result * small(n % p, r % p) % p
        if result == 0:
            return 0
        n //= p
        r //= p
    return result
